import java.util.Scanner;

public class HotelTariff {
    // Instance variables
    private String name;
    private int nod;
    private double tariff;
    private double amount;

    // Default Constructor
    public HotelTariff() {
        name = "";
        nod = 0;
        tariff = 0.0;
        amount = 0.0;
    }

    // Method to accept customer details
    public void accept() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Customer Name: ");
        name = in.nextLine();
        System.out.print("Enter Number of Days Stayed: ");
        nod = in.nextInt();
        System.out.print("Enter Daily Room Tariff (Rs): ");
        tariff = in.nextDouble();
    }

    // Method to compute total bill amount
    public void calculate() {
        double baseAmount = nod * tariff;
        double discount = 0.0;

        // Long-stay discount of 5% if stay > 7 days
        if (nod > 7) {
            discount = 0.05 * baseAmount;
        }

        double netBase = baseAmount - discount;
        double luxuryTax = 0.0;

        // 10% Luxury tax if base amount exceeds 10,000
        if (baseAmount > 10000.0) {
            luxuryTax = 0.10 * netBase;
        }

        amount = netBase + luxuryTax;
    }

    // Method to display invoice
    public void display() {
        System.out.println("\n=========== HOTEL GRAND PALACE BILL ===========");
        System.out.println("Customer Name         : " + name);
        System.out.println("Days of Stay          : " + nod);
        System.out.println("Daily Room Tariff     : Rs. " + tariff);
        System.out.println("Total Payable Amount  : Rs. " + amount);
        System.out.println("================================================");
    }

    // Main method for testing
    public static void main(String[] args) {
        HotelTariff guest = new HotelTariff();
        guest.accept();
        guest.calculate();
        guest.display();
    }
}
```

