import java.util.Scanner;

public class ReverseWordsInPlace {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter a sentence:");
        String sentence = in.nextLine().trim();

        // Append a space to facilitate word extraction
        sentence = sentence + " ";
        String currentWord = "";
        String resultSentence = "";

        for (int i = 0; i < sentence.length(); i++) {
            char ch = sentence.charAt(i);

            if (ch != ' ') {
                currentWord += ch;
            } else {
                if (currentWord.length() > 0) {
                    // Reverse currentWord
                    String reversedWord = "";
                    for (int j = currentWord.length() - 1; j >= 0; j--) {
                        reversedWord += currentWord.charAt(j);
                    }
                    resultSentence += reversedWord + " ";
                    currentWord = ""; // Reset for next word
                }
            }
        }

        System.out.println("\nOriginal Sentence : " + sentence.trim());
        System.out.println("Transformed Sentence: " + resultSentence.trim());
    }
}
```

