import java.util.Scanner;

public class DisariumNumberCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a positive integer: ");
        int num = sc.nextInt();

        if (num <= 0) {
            System.out.println("Please enter a valid positive integer.");
            return;
        }

        // Count number of digits
        int temp = num;
        int digitCount = 0;
        while (temp > 0) {
            digitCount++;
            temp /= 10;
        }

        // Calculate positional power sum from right to left
        temp = num;
        double sum = 0.0;
        int pos = digitCount; // Highest position is the length
        while (temp > 0) {
            int digit = temp % 10;
            sum += Math.pow(digit, pos);
            pos--;
            temp /= 10;
        }

        // Verification
        if ((int) sum == num) {
            System.out.println(num + " is a DISARIUM NUMBER.");
        } else {
            System.out.println(num + " is NOT a Disarium Number (Sum = " + (int) sum + ").");
        }
    }
}
```

