import java.util.Scanner;

public class MatrixMinMaxLocation {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter number of rows M (<= 10): ");
        int m = sc.nextInt();
        System.out.print("Enter number of columns N (<= 10): ");
        int n = sc.nextInt();

        int[][] mat = new int[m][n];
        System.out.println("Enter elements for " + m + "x" + n + " matrix:");
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                System.out.print("mat[" + i + "][" + j + "]: ");
                mat[i][j] = sc.nextInt();
            }
        }

        // Initialize min and max with the first element
        int maxVal = mat[0][0], maxRow = 0, maxCol = 0;
        int minVal = mat[0][0], minRow = 0, minCol = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] > maxVal) {
                    maxVal = mat[i][j];
                    maxRow = i;
                    maxCol = j;
                }
                if (mat[i][j] < minVal) {
                    minVal = mat[i][j];
                    minRow = i;
                    minCol = j;
                }
            }
        }

        // Print matrix
        System.out.println("\nInput Matrix:");
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                System.out.printf("%5d", mat[i][j]);
            }
            System.out.println();
        }

        System.out.println("\nMaximum Element = " + maxVal + " at Row " + maxRow + ", Column " + maxCol);
        System.out.println("Minimum Element = " + minVal + " at Row " + minRow + ", Column " + minCol);
    }
}
```

