import java.util.Scanner;

public class MenuSeriesComputation {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("========== SERIES MENU ==========");
        System.out.println("1. Generate Fibonacci Series");
        System.out.println("2. Calculate Series Sum: x + x^2/2 + x^3/3 + ... + x^n/n");
        System.out.print("Enter your choice (1 or 2): ");
        int choice = in.nextInt();

        switch (choice) {
            case 1:
                System.out.print("Enter number of terms (n >= 1): ");
                int n1 = in.nextInt();
                if (n1 <= 0) {
                    System.out.println("Invalid number of terms.");
                    break;
                }
                System.out.println("Fibonacci Series up to " + n1 + " terms:");
                int a = 0, b = 1;
                for (int i = 1; i <= n1; i++) {
                    System.out.print(a + (i == n1 ? "" : ", "));
                    int next = a + b;
                    a = b;
                    b = next;
                }
                System.out.println();
                break;

            case 2:
                System.out.print("Enter value of x: ");
                int x = in.nextInt();
                System.out.print("Enter number of terms n (n >= 1): ");
                int n2 = in.nextInt();
                if (n2 <= 0) {
                    System.out.println("Invalid number of terms.");
                    break;
                }
                double sum = 0.0;
                for (int i = 1; i <= n2; i++) {
                    sum += Math.pow(x, i) / i;
                }
                System.out.printf("Sum of series S = %.4f\n", sum);
                break;

            default:
                System.out.println("Invalid Choice. Please choose 1 or 2.");
        }
    }
}
```

